const int TRIG = 9, ECHO = 10;
const int RED = 4, YLW = 3, GRN = 2;

void setup() {
  Serial.begin(9600);
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  for (int p = 2; p <= 4; p++)
    pinMode(p, OUTPUT);
}

void loop() {
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  long cm = pulseIn(ECHO, HIGH, 30000) / 58;  // 0 when nothing echoes back
  Serial.print(cm);
  Serial.println(" cm");

  // exactly one light is on at a time
  digitalWrite(GRN, cm > {{p:far}});
  digitalWrite(YLW, cm > {{p:near}} && cm <= {{p:far}});
  digitalWrite(RED, cm <= {{p:near}});
  delay(60);
}

sources.content:
const int TRIG = 9, ECHO = 10;
const int RED = 4, YLW = 3, GRN = 2;

void setup() {
  Serial.begin(9600);
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  for (int p = 2; p <= 4; p++)
    pinMode(p, OUTPUT);
}

void loop() {
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  long cm = pulseIn(ECHO, HIGH, 30000) / 58;  // 0 when nothing echoes back
  Serial.print(cm);
  Serial.println(" cm");

  // exactly one light is on at a time
  digitalWrite(GRN, cm > 30);
  digitalWrite(YLW, cm > 15 && cm <= 30);
  digitalWrite(RED, cm <= 15);
  delay(60);
}
